"use client";

import { useRouter } from "next/navigation";
import { useState } from "react";
import { useAgent } from "../context/AgentContext";

const STARS = [1, 2, 3, 4, 5];

export default function ImprovePage() {
  const router = useRouter();
  const { agentDef, setAgentDef, runResult } = useAgent();

  const [rating, setRating] = useState<number>(0);
  const [hovered, setHovered] = useState<number>(0);
  const [comment, setComment] = useState("");
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [suggestion, setSuggestion] = useState<string | null>(null);
  const [accepted, setAccepted] = useState(false);

  const hasRun = runResult !== null;
  const canSubmit = rating > 0 && !loading && !accepted;

  async function handleGetSuggestion() {
    setLoading(true);
    setError(null);
    setSuggestion(null);

    try {
      const res = await fetch(
        `${process.env.NEXT_PUBLIC_API_URL ?? "http://localhost:8000"}/improve`,
        {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({
            current_instructions: agentDef.agentInstructions,
            rating,
            comment: comment.trim() || "No comment provided.",
          }),
        }
      );

      if (!res.ok) {
        const body = await res.text();
        throw new Error(`API error ${res.status}: ${body}`);
      }

      const data = await res.json();
      setSuggestion(data.suggestion);
    } catch (err) {
      setError(err instanceof Error ? err.message : "Unknown error");
    } finally {
      setLoading(false);
    }
  }

  function handleAccept() {
    if (!suggestion) return;
    setAgentDef({
      agentInstructions: agentDef.agentInstructions + "\n\n" + suggestion,
