          <button
            onClick={() => router.push("/test")}
            className="underline font-medium"
          >
            Go to Test
          </button>{" "}
          to run your agent first.
        </div>
      )}

      {/* Last run summary */}
      {hasRun && (
        <div className="mb-8 rounded-lg border border-gray-200 dark:border-gray-700 bg-white dark:bg-gray-800 px-4 py-4">
